        "synopsis":  "여친 있는 남자의 아내가 되어 버렸다. 음, 건드리지 말아야겠지? “그럼 넌 바닥에서 자.” “뭐?” 싫은 눈치다. 그래, 바닥은 딱딱하지. 그렇다면 어쩔 수 없다. “손만 잡고 잘게. 누나 믿지?” 그런데 어쩌다 남편과 첫날밤에 침대를 부숴 버린 걸까……. * 황제의 눈밖에 나 유폐당한 황녀, 아리스티네. 사실 그녀는 미래와 현재, 과거를 모두 볼 수 있는 \u003c제왕안\u003e의 소유자였다. 정략혼의 희생양이 된 그녀는 괴물 같은 야만인과 맺어지는데……. “가장 귀한 것을 내 신부님께 드려야지.” 괴물이라던 예비 남편님이 지나치게 멀쩡하다. 하지만 이 떡은 남의 떡. ‘돈이나 벌어야지.’ 자고로 황금 보기를 내 것같이 하라고 했다. \u003c남편은 됐고, 돈이나 벌겠습니다.\u003e 과연 그녀는 돈방석에 앉아 자유롭게 사는 꿈을 이룰 수 있을까? 아니면 두 마리의 토끼를 동시에 잡게 될까?",
