        "synopsis":  "사자 가문에서 태어난 유약한 다람쥐 수인 베아티. 그 탓에 수도 이모집에서 구박데기로 살다 유일한 친구이자 약혼자인 2황자에게 꿈을 이루기 위해 떠나겠다고 말한 순간, \u0027리테르 너 이 나쁜 새끼…!\u0027 그놈의 독니에 죽었다. 다시 눈을 떴더니 2왕자와 엮이기 전의 어린 시절. 이럴 때 필요한 건 뭐? 스피드. 바로 몸만 빼내 친부 사자공의 영지로 튀었다. 비록 환영받진 못하겠지만 그래도 앞으로 발견될 이 엄청난 비법을 가져가 준다면, 내쫓지는 않을 거…… \"어서 오십시오, 아가씨!\" \"세상에! 언제 이렇게 자라셔서….\" \"아가씨가 저 앙증맞은 두 발로 걸으신다!\" ……응? 왜 이렇게 환영하지? 저거 설마 내 동상이야?",
