        "synopsis":  "\u0027쓰레기 머학생\u0027이었던 수레기, 의대생이 되어 돌아왔다. 제멋대로 대학생활을 보내며 전공이었던 수학을 잔뜩 싫어했던 수레기는 졸업 후 수능을 다시 보고 의대에 합격한다. 늦은 나이에 다시 신입생이 되어 시작하는 두 번째 대학생활! 이번에는 이전처럼 심각한 아싸처럼 살지도, 공부도 던지지 않기로 결심하며 재활용 머학생이 되어보리라 다짐하는 수레기. 하지만 그녀를 기다리고 있는 건 어마어마한 의대의 공부량... 그리고 한참 어려서 다가가기 힘든 동기들... 과연 수레기는 제대로 \u0027재활용\u0027 되어 대학생활을 지낼 수 있을 것인가? 현재진행형인 의대생의 일상 이야기",
