        "synopsis":  "가장 좋아하던 소설 속, 요절하는 최애의 전 부인으로 빙의했다. ‘어차피 지난 생에 미련도 없었는데, 뭐. 이렇게 된 거 최애 덕질이나 실컷 해야지!’ 그렇게 생각했는데, 원작에 없던 힘의 발현으로 살아남아 버렸다. 심지어 그사이 시댁 식구들을 너무 잘 꼬셔 버렸는데……. “수수료보다 아키드 영상에 더 목숨 거는 사람은 너뿐일 거다.” 한량기 다분한 성격 파탄자1, 시아버지가 내 덕질을 돕질 않나. “그럼 귀엽게 생기지 말지 그랬니. 너같이 귀여운 애들을 노리는 흉악범이 세상엔 많단다.” 왕년에 ‘하인트의 미친개’라 불리던 성격 파탄자2, 시어머니가 냉대는커녕 나를 심하게 과보호한다. 그리고 순진하기만 했던 남편이 시도 때도 없이 유혹하기 시작하는데……. “로네의 머리카락은 꼭 솜사탕 같습니다.” “제 머리가 좀 부스스하긴 하죠.” “전혀요. 부들부들해서 계속 만지고 싶다는 의미로 한 말인데.” 그동안 나는 그에게 나란 존재가 너무 위험하다고 생각했다. 그런데…… “로네, 이제 누가 더 위험한지 감이 옵니까?” 순진한 줄만 알았던 내 아키드가 사실은 끼부림에 천재였던 걸까?!",
