        "synopsis":  "갤러리 화담의 관장 차지원. 뛰어난 능력에 수려한 외모까지, 누가 봐도 완벽해 보이는 이 남자에게는 은밀한 능력 하나가 있다. 바로 귀신을 보고, 귀신의 그림을 그려 처리할 수 있다는 것. 여느 날처럼 그림 하나로 사람을 괴롭히는 영혼을 처리한 지원은 죽은 자를 적합한 절차 없이 보냈다는 이유로 \u0027중천\u0027에 끌려가게 된다. 그리고 망자를 심판하는 곳 중천, 바로 그곳에서 중천의 주인인 가온을 만나게 된다. 처음엔 호승심이었다. 지신을 거들떠보지도 않는, 초월적 존재에 대한 호기심이라 생각했다. 투지라 부르기엔 다소 복잡한 감정이었지만 달리 설명할 방법은 없었다. 그래, 처음엔 그랬는데… 왜 지금은 예뻐보이는 거지? 천년의 임무를 맡고 망자를 심판하는 일로 평생을 보내고 30년이 남은 가온. 그 흔한 아메리카노도 먹어 보지 못한 그녀의 인생에 처음으로 자신에게만 따뜻하게 대하는 남자 차지원이 스며들기 시작한다. 함께 죽은 자들을 심판하고 구원하는 두 사람. 그들은 서로를 구원할 수 있을까.",
