        "synopsis":  "뼈대 있는 후작 집안, 펑펑 써도 남을 재물, 반반한 얼굴까지 가진 리디아 에반시. 그녀가 갖지 못한 건 단 하나, 바로 남자 보는 눈! 천한 몸에서 태어난 황자에게 빠져 간쓸개 다 바쳐 황제가 되고 싶단 꿈까지 이뤄줬더니, 자신의 먼 친척 지젤과 바람이 나버렸다. 그리하여 리디아는 지젤과 함께 독을 먹고 죽어 진정한 집착의 끝이 무엇인지 보여줄 결심을 한다. 하지만 계획은 실패하고, 리디아는 척박하고 열악한 노역장으로 끌려간다. 얼마 뒤, 춥고 열악한 노역장에 닥친 전염병으로 리디아는 가늘고 하얀 손을 떨며 조용히 죽음을 기다린다. 왜 이렇게 남자에 미쳐서 멍청하게 굴었을까? 다시 그때로 돌아간다면 뺨 한번 세게 쳐주고 싶다. 정신 좀 차리라고. ...그런데, 정말로 기회가 왔다. 지젤의 찻잔에 독을 타던 바로 그 오후, 티타임으로! 짝! 리디아는 얼른 뺨부터 후려치고 새 삶을 시작한다. 그녀를 버렸던 리처드와 그녀를 기만한 지젤, 그리고 자신의 목숨으로 거래를 한 데본에게 안겨줄 복수를. 그러기 위해서는, 모두가 탐내는 제국의 검, 아르센 에디스가 필요하다. 리디아는 아르센에게 접근하고 당당하게 회귀했음을 밝히며 도움을 요청한다. 반신반의하던 아르센은 일단 믿고 지켜 보기로 하고 리디아와 함께 생활을 시작한다. 그런데... 리디아를 보는 아르센의 눈빛이 점점 이상해진다?",
