        "synopsis":  "여자 아이돌 경연 프로그램에 참가한 ‘성가연’. 심사위원이자 더러운 성질머리의 톱스타 ‘소우’와 경연 내내 혐관 케미로 서사를 쌓으며 쑥쑥 성장하더니 급기야 최종 선발 무대까지 진출한다. 하지만 결과는 데뷔조 탈락. 아쉬움을 달랠 틈도 없이 ‘소우’의 영안이 열려 귀신을 보는 것으로도 모자라 곧 죽을 운명이라는 걸 알게 되는데. 그리고 그 원인이 성가연, 자신 때문이라는 것! 소우를 귀신으로부터 천 번 구해야 가연의 내세도 편안해진다는 말에 남장을 하고, 이름도 바꾼 후 소우의 경호원으로 취직하는데…! 경호도, 퇴마도 Y튜브로 배운 ‘성우연’. 오늘부터 퇴마사로 데뷔합니다!",
