        "synopsis":  "아라크레네 공작가의 손녀로 태어났지만 이능을 각성하지 못해 버림 받은 리에르샤. 하지만 견고했던 가문에 황실의 군대가 쳐들어오고 삶의 끝에서 리에르샤는 미처 알지 못했던 진실을 알게 된다. “보십시오. 당신 하나 지키려고 지금 누가 죽었는지.” 철저히 혼자라고 생각했다. 하지만 자신을 위해 가문이 숨기고 있었던 비밀을 알아챈 순간, 리에르샤는 과거로 회귀하고 마는데. 하찮은 자신 때문에 가족들이 다치게 할 순 없다. 과거로 돌아온 리에르샤는 가족을 위해 떠나기로 하지만 문제는, 어려도 너무 어린 4살이 되어 버렸다는 것! 게다가 과거엔 없었던 이능을 급하게 각성하기까지? 이렇게 된 이상, 리에르샤가 할 수 있는 건 세 가지였다. 첫 번째. 가문의 배신자를 같은 편으로 포섭하고- 두 번째. 뿔뿔이 흩어진 가족을 모은다. 세 번째는 어렵게 발현해 낸 이능으로 가족들을 지킨다! 말랑뽀짝 리에르샤의 \u003c이 가문은 막내가 살립니다\u003e",
