        "synopsis":  "모든 직장인이 그렇듯, 월요일을 무지하게 싫어하는 진 한. 일요일 밤 자고 난 뒤 출근했는데, 월요일이 아닌 화요일이었다 통째로 사라진 월요일의 기억. 그런데 제대로 사고를 쳤다. 직장내 최고 퀸카 여사원에게 공개적으로 고백을 해 버린 것! 그리고 다시 또 돌아온 다음 주 평일. 이번에도 일요일에 잠이 든 그는 화요일에 일어나 버렸다!? 진짜로 월요일의 기억이 사라져 버린 상태. 이번에는 회사 대표에게 기가 막힌 프로젝트 건의를 해서 온 회사를 발칵 뒤집어 놓았다! 이렇게 월요일이 될 때마다 또 다른 자신이 깨어나 하나씩 큰 사고를 치는 주인공 진 한. 하나같이 비싼 차를 산다든지, 미모의 여직원에게 용감히 대쉬해 연애에 골인한다든지, 소심한 성격 탓에 속으로만 간직하던 기획안을 용감하게 건의한다든지, 자신의 ‘워너비’ 성향을 마음껏 발산한다. 그러면서 자연스레 사람들은 월요일의 그를 기대하게 되고, 진 한 본인도 차츰 자신감을 얻어가게 되는데.....",
