        "synopsis":  "28세. 미혼의 이삼탁은 다니던 회사를 그만두고 농사를 짓겠다며 고향에 내려와 밭을 구입했지. 그러고는 자신의 직업을 농부라고 인쇄한 명함을 만들어 만나는 이들의 손에 쥐여줬어. 귀촌을 궁금해하는 동네 분들에게 귀찮은 질문과 험담 따위를 듣게 될까 봐. 이삼탁은 명함을 뿌린 거야. 뿌렸더니, 그 명함에 박힌 ‘농부’를 동네 사람들은 이삼탁의 호칭으로 삼아버렸네. 그렇지 고유명사가 된 거야. 이삼탁이 농사에 서툴러 말아먹어도 사람들은 농부라고 불러주는 거 있지. 조롱하듯이. 이삼탁이 농작물에 해를 끼치고 있는 짐승을 사냥한다며 허구한 날 엽총 들고 산속을 뛰어다녀도 사람들은 ‘농부야’하고 부르는 거야. 아니 아니. 혹시, 만약에, 진짜! 이삼탁이 ‘그냥 쉬고 있다’고 하자. 그래도 농부라고 불러줄걸. 그 동네 사람들은. 이삼탁이 원하니까.",
