        "synopsis":  "\u003c나는 개로소이다\u003e 어느 날, ‘말’을 하게 된 반려견 채드와 실패한 웹툰 작가 최충의 좌충우돌 모험기. 웹툰 작가 최충의 반려견은 왜 갑자기 ‘말’이 터진 걸까?! \u003c삐라\u003e 1950년, 동경 유학을 다녀온 후 일일 만화를 연재하던 박종수는 같은 일간지의 여류 만화가 김예원을 흠모하게 되고 그녀에게 데이트 신청을 한다. 약속 장소인 \u003c베로나 성당\u003e에 도착한 종수는 두근두근한 마음으로 예원을 기다리는데, 하필 그날은 1950. 6. 25. 한국전쟁 개전일. 3년 후, 군에 강제징집된 종수는 그날 만나지 못한 예원을 그리워하며 군 정보과에서 대북 심리전단 ‘삐라’를 제작하며 연명하고 있다. 그러던 어느 날, 북에서 대량 살포된 삐라를 주운 종수는 북측 삐라가 자신이 흠모하던 김예원이 그린 것이라는 것, 또한 그녀가 삐라를 통해 자신에게 \u003c메시지\u003e를 보내고 있다는 과대망상에 빠지는데... 과연 종수의 망상은 현실일까? 정신병일까?",
