        "synopsis":  "엄청난 빚만 남기고 아버지가 돌아가신 날, 리비아는 자신이 전생에 죽기 전 읽었던 소설 속 엑스트라로 환생했다는 사실을 깨달았다. 거기까지는 좋았는데……. 자신이 또 시한부, 그것도 피부에 검은 꽃이 피며 죽는 마화병에 걸렸단다. 병을 치료할 유일한 방법은 이 세계의 흑막가인 ‘메르체데스 공작가의 가보.’ 하는 수 없지. ‘적당히 도움만 주고 가보로 병만 치료하면 떠나자!’ 그렇게 리비아는 메르체데스 공작가의 입주 가정교사로 위장 취업했다. * * * 가보를 찾고 병을 치료했다. 목적을 이뤘으니 이제 조연답게 조용히 사라지려 했는데……. “제가 잘못했어요. 가지 마세요. 선생님 없으면 전 못 살아요.” 소악마라 불리던 소공자는 떠나지 말라며 매달리고. “마땅히 신을 섬기고 성녀님을 모셔야 할 제가, 왜 당신에게 온 것인지. 당신은 아십니까?” 원작 여주를 따라야 할 성기사가 내게 기사의 맹세를 하고. \"리비아 씨, 제 운명의 나비는 당신입니다.\" 제국 최고 정보 길드의 마스터가 나를 유혹하려 하질 않나, “소공자 말고 황자의 가정교사가 되어줄 수 없겠나? 자네가 아주 탐나서 말이야.” 원작 여주에게 빠져 간이고 쓸개고 다 줬어야 할 남주가 어째서인지 나를 스카웃하겠다며 들이댄다. 무엇보다……. “가려면 어디 한 번 가보든가. 뒷감당할 자신 있으면.” 저기요, 그거 협박 아닌가요……? ‘대체 뭐가 어떻게 돌아가는 건데!’ 나는 그저 병을 치료하고 싶었을 뿐인데, 무언가 단단히 잘못된 것 같다.",
