        "synopsis":  "가문의 권능을 가지지 못한 채 태어난 아이, 클로버. 권능이 없다는 이유로 외가에 맡겨진 아이는, 못된 이모와 사촌오빠의 구박 속에서 자라게 된다. ‘클로버, 갠차나.’ 하지만 나날이 심해지는 외가의 구박속에 언젠가는 아빠가 데리러 올 거라고 굳게 믿던 클로버였지만 이제는 정말 꼼짝없이 버려진 건가 싶던 차에…… “클로버, 아빠 왔다.” 아빠가 나타났다. 그것도 클로버가 그토록 바라던 모습으로. *** 못된 이모가 클로버에게 늘 하던 말이 있었다. 클로버는 쓸모없고 권능은 보잘것없으니까, 집에 돌아가도 분명히 미움받을 거라고. 하지만. “권능이 없어도 똑같이 사랑했을 거다, 너는 내 딸이니까.” 클로버의 기대보다 훨씬 더 상냥하고 다정한 아빠와. “완두콩, 내 옆에 앉을래? 오빠가 밥 먹여 줄까?” “내 동생, 너를 만나게 될 날을 아주 오래 기다렸어.” 집에 돌아온 클로버를 환영해 주는 두 오빠들, “클로버, 누구도 너를 건드릴 수 없어, 내가 있는 이상은.” ……조금은 과보호하는 것 같지만, 클로버를 아끼고 사랑해 주는 언니까지. 사랑하는 가족들 사이에서 클로버는 생각했다. 어쩌면 이모가 틀렸을지도 모른다! *** 기억해 클로버, 새싹은 꽃의 과거야. 꼬마 새싹 클로버의 근사한 성장기!",
