        "synopsis":  "행성 테베에서 죽음의 군주, 살아있는 죽음이라 칭송받은 최강의 네크로맨서. 세레지아의 협력을 얻어 자력으로 귀환에 성공하지만 부작용으로 모든 힘을 잃고 연약한 소녀의 모습이 되었으며, 대인기피증까지 생겨버렸다. 그러던 와중 인터넷 방송을 하는 초보 네크로맨서 송하연을 보고 조언을 헤주는 대가로 사기가 담긴 마석을 받아 다른 데서 사기를 조달하면 사령술을 쓸 수 있는 것을 알게 된다. 얼마 안가서 S급 헌터이자 네크로맨서인 헬레나와 엮이며, 자신의 힘이 사라진 것이 아닌 모종의 힘에 의해서 봉인된 상태라는 것과 상태창이 나타난 것을 보고 헌터로서 레벨을 올리게 되면 힘을 되찾을 수 있다는 것을 알게 되어 헌터가 되기로 결심한다. \"죽음마저 극복한 명계의 군주가 마침내 지구로 돌아왔다. 차원 이동 부작옹으로 아싸 찐따가 된 채\"",
