        "synopsis":  "\u0027심장은 여전히 그를 사랑한다고 말했지만, 머리는 그 사랑을 거부했다. 그것은 꽤나 묘한 기분이었다. 나지만 내가 아닌 느낌이었다.\u0027 햇빛을 받아 금발처럼 보이는 금갈색 머리카락이 허리까지 내려와 굽실거렸다. 거울 안에는 반짝이는 짙은 녹색 눈동자를 가진 아이가 눈을 깜빡이고 있었다. \"비욘느 롯사 엘리언트.\" 익숙하지만 익숙하지 않은 울림이 입안에서 맴돌았다. 천천히 거울을 다시 들여다보았다. 통통한 젖살이 있던 아이의 모습이 사라지고 성인이 된 얼굴이 거울에 비쳤다. \u0027잊지 마. 나는 바로 너야.\u0027 광기에 젖은 녹색 눈동자가 거울 안에서 나를 똑바로 바라보고 있었다. 그녀의 붉은 입술이 천천히 달싹였다. \u0027이지아.\u0027 순식간에 그녀의 모습이 사라지고 피곤에 지친 여자의 얼굴이 나타났다. 방금 전의 그녀와는 다른, 그러나 너무나 익숙한 얼굴이었다. 마치, 한 편의 극을 보는 것처럼 나는 제삼자가 되어 그녀의 일생을 보았다. 지금의 나는 죽은 비욘느의 회귀인가? 지루한 일상의 일탈을 원했던 이지아인가? 아니면 미래를 보고 온 어린 비욘느인가?",
