        "synopsis":  "보육원에서 자라난 소년, 데미안. 자신을 후원하던 은인이 친부였다는 사실을 알게 된 그는 가문의 그늘에서 벗어나기 위해 타국의 전쟁에 몸을 던진다. 살아 남아야 할 이유도, 목표도 없던 전쟁터. 그 황폐한 시간 속에서 어느날 봄바람 같은 한 통의 편지를 받게 된다. 「안녕하세요, 이름도 얼굴도 모르는 어느 군인님. 이렇게 인연이 닿게 되어 기쁩니다. 저는 풍경이 아름다운 시골에 사는 한미한 가문의 영애입니다. 그렇게 대단한 사람이 아닌지라 자기소개를 할 때 내세울 만한 것이 없네요.」 자신을 린트레이라 소개한 귀족 여성. 우연히 시작된 펜팔은 차츰 데미안의 유일한 위로가 되고 편지 너머의 그녀는 그에게 처음으로 \u0027살고 싶은\u0027 이유가 된다. 이후 불의의 사고로 제대하게 된 데미안, 펜팔 상대였던 그녀를 찾아 편지의 주소로 찾아가지만... \"그 집은 얼마 전 큰불이 나서 전소됐네\" “자네가 말한 린트레이가 그 집 하녀를 말하는 것이라면, 그녀는 죽었소.” 불에 타버린 저택, 뒤엉킨 증언들... 레이디 린트레이는 정말 존재했던 인물일까, 아니면 처음부터 거짓이었을까. 혼란에 빠진 데미안은 그녀가 죽었을 리 없다는 희미한 희망 하나를 품은 채, 그녀를 찾아 수도 니히로로 향한다. 그곳에서 데미안은 린트레이를 다시 만날 수 있을까? 그리고 끝내 전하지 못한 말에, 답을 받을 수 있을까?",
