        "synopsis":  "[엠블럼 앞에서 그레이 찾는 소리 해라] 루티나스 제국에서 가장 사랑 받는 속담에 등장하는 이 두 가문은 온 나라가 알아주는 원수 가문이다. 검술 명가인 두 가문 중 나는 엠블럼 공작가의 금지옥엽, 세르시아 엠블럼으로 환생했다. 전생에 형사로서 구를 대로 구르다가 범죄자의 손에 목숨을 잃은 내게 보상이라도 해주는 것 처럼 이번 생은 꿀맛 같았다. 하지만....... \"시시해지겠네, 너. 너도, 엠블럼도 약해질 거니까.\" \"다시 말해봐, 이 새끼야!\" 갓난 아기 때부터 치고 박고 싸우고 경쟁하며 철천지 원수처럼 자라온 그레이 가문의 후계자 에녹과 약혼을 하게 되었다! 두 가문의 화합을 도모하려는 어머니들의 계략으로 인해! 눈만 마주치면 냅다 주먹과 검이 오고가던 에녹과 약혼이라니, 혀라도 깨물고 싶다는 심정으로 약혼식장에 도착한 나는 예기치 못했던 악연과 조우하고야 말았다. \"나 안 보고 싶었어요, 형사님?\" \"너 설마!\" 현생의 원수 에녹 그레이가, 내 전생의 원수였다. 전생의 기억을 자각한 에녹은 답지도 않은 달콤한 목소리와 반쯤 돌아간 눈으로 진짜 내 옆자리를 꿰어차려고 들었고, 에녹의 이 변화는 잠잠하던 내 주변을 점차 변화시켜만 갔다. \"그레이 경에게 그대의 마음까지 빼앗기려고 여태 지켜만 봤던 건 아니야.\" 나의 주군인 황태자부터, \"형식상의 약혼이라고 했기에 참았던 겁니다. 단장님께서 그레이 경에게 흔들리는 것까지는 용납 못해요.\" 평생을 함께해야 할 부관까지 에녹에게 이를 드러내며 경계하기 시작했다. 물론 그 중 나를 가장 괴롭게 하는 것은, \"형사님이 그렇게 죽은 뒤에 내가 어떻게 미쳐갔는지. 세르시아, 너는 몰라.\" 전생의 원수이자 현생의 라이벌인 에녹 그레이. 이 자식이었다.",
