        "synopsis":  "아르바이트로 생계를 이어가며 \u0027천애고아\u0027를 전전하는 백수 주인공. 무료한 일상 속, 유일한 낙은 온라인 게임 ‘신이 버린 세계(God Forsaken World)’였다. 지루한 현실을 잠시나마 잊게 해주는, 그에게는 소중한 탈출구 같은 게임. 그러던 어느 날, 게임을 즐기던 중 어디선가 들려온 정체불명의 목소리. 정신을 차려보니… 그는 게임 속 세계 한가운데에 있었다! 이왕 게임 안에 들어왔으면 멋지고 강력한 주인공이 되어 있을 줄 알았건만— 그가 빙의한 인물은 제국의 망나니이자 실패한 제3황자, ‘길로샨 엘로 디 발트’였다. 게다가 상황은 최악. 눈을 뜬 그 순간, 누군가에게 살해당하기 직전이었다! 뚱뚱하고 한심하다는 평가를 받는 황자의 몸. 하지만 주인공에겐 이 세계를 빠져나갈 단 하나의 무기, 바로 ‘공략집’이 있었다. 누구보다 게임을 잘 아는 유저만이 갖고 있는, 생존의 열쇠! 비틀거리는 황자와 그를 충직하게 따르는 기사 ‘칼스’, 그리고 무섭지만 믿음직한 마법 스승 ‘티르바엔’. 이들이 함께 써내려가는 한 판의 게임, 아니 현실보다 더 치열한 모험이 시작된다! “망나니 황자의 몸으로 살아남기? 게임처럼 쉽진 않을 걸?” 예측불허 판타지 속, 웃음과 전투가 끊이지 않는 생존 액션 판타지!",
