        "synopsis":  "축복과 악운을 타고난 북부의 공작 레녹스 칼라일에게 삶은 늘 쉽고 명료했다. 생과 사, 흑과 백 원하는 것은 빼앗아 취하고, 쓸모없어진 것은 버리면 그만. 7년 전, 부모의 복수를 조건으로 그를 찾아왔던 계약 연인도 예외는 아니었다. ‘제가, 첫눈에 반했거든요.’ 만족스러운 거래였다. 영리하고 비밀스럽고, 눈치까지 빠른 줄리엣 모나드. 소꿉장난 같은 연인 놀이가 질리면 언제든 쉽게 끊어낼 수 있는 편리한 관계. 그렇게 확신했다. “이제 그만할래요. 더이상 전하를 사랑하지 않아요.” 겨울처럼 고요한 얼굴로 봄처럼 안겨오던 여자가 고백하듯 이별을 말하고 가장 날카로운 비수로 그를 찌르고 달아나기 전까지는. * 몰락한 백작 영애, 공작의 철없는 시한부 연인. 줄리엣 모나드에게 삶은 늘 공평하고 잔인했다. 운명이 그녀에게 두 번째 삶을 주고 무엇 하나 바꿀 기회는 허락하지 않은 것처럼. 안아보지 못한 아기, 구하지 못한 부모님. 여름처럼 오만하고 가을처럼 잔인한 첫사랑이었던, 그러나 이번에도 결국 그녀를 영원히 잊을 남자. 닫힌 문 앞에서 줄리엣은 생각했다. 손안의 열쇠는 작고 초라하고, 눈앞의 견고한 문은 열리지 않을 것이다. 발버둥 쳐도 정해진 운명을 벗어날 수 없다면 뭘 해야 할까? 줄리엣은 첫사랑이었던 남자에게 계약을 제안했다. 내 복수를 도와주면 원하는 걸 줄게. 똑같이 기만당하고 버림받느니, 이번에는 차라리 이용하고 이용당하다가 먼저 제 방식대로 이 관계를 끝내주겠노라고. 계약 연인을 버리고 도망친 7년째 밤. 차가운 오해와 배신이 들끓는 추격전의 끝에서 줄리엣은 처음으로 견고한 운명이 삐걱이며 어긋나는 소리를 들었다. “네가 졌어, 줄리엣. 그러니까 포기해.” “도망치려거든, 내 애를 가진 걸 들키지 말았어야지.” 문이 열리고, 비밀이 탄로 났다. 나비의 날갯짓이 불러온 폭풍으로부터 아주 오래 기다려온 약속과 복수가 시작되었다.",
