        "synopsis":  "[수린당 성군전] 선계와 인간계를 이을 단 한 명의 성군, ‘한울’. 지덕체를 두루 갖춘 완벽한 아이의 탄생에 선계의 신들은 신이 났다. 그것도 아주 지나치게! 과도한 기대는 때론 독이 될 수도 있는 법. 한울이를 금쪽이가 되지 않게 밝고 바른 아이로 키울 수 있을까? 성군의 운명을 타고난 이 아이는 과연 진정한 성군이 될 수 있을까? 본격 우리 아이 성군 만들기 프로젝트! * * * [수린당 -비늘 고치는 집-] 이런게 축복이라고? 운명을 바꾸기 위한 자매의 여정! 수린당의 역사는 먼 옛날 봉황의 비늘을 찾아준 자매에게서 시작된다. 봉황은 자매에게 각각 마르지 않는 재능과 성군을 낳을 운명을 축복으로 내렸고 그 축복은 대대로 이어져 현재 수린당 자매에게 이른다. 천재적인 바느질 실력을 갖췄지만 영수들이 무서운 장녀 은침과 비혼주의자이지만 성군의 탄생을 위해 결혼을 종용받는 동생 홍실 이들은 자신들의 운명이 저주스럽다. 그런 자매 앞에 비늘을 다친 도망자 봉이 나타나게 되고 비늘을 고쳐주는 대가로 동생의 축복을 풀어준다는 약속을 받아낸 은침은 그와 함께 신비롭고 로맨틱한 여정을 떠나게 되는데... 과연 자매는 모든 유혹과 역경을 물리치고 축복 풀기에 성공할 수 있을까?!",
