        "synopsis":  "책 속에 처음 들어왔을 때 나는 그냥 살아남는 것이 목표였다. 최대한 가늘고! 길고! 행복하게! 그래서 아등바등 최선을 다해 살았다. 슬슬 독립해서 꽃길을 걸어보려 했는데. “어딜 가더라도 주인님 옆자리는 내 거예요. 평생 내 머리 쓰다듬어주기로 약속했잖아. 그렇지요?” 원작에서는 내게 찔려죽는 최강자 남주가 집착 어린 눈동자로 나를 응시했다. 아니라고 했다가는 세계를 멸망시킬 것 같다. “응, 내가 걔 죽여줄게. 그럼 너도 기쁘겠지?” 아무래도 다섯째 오빠는 상당히 미쳐 있는 듯하다. “여기서 여기까지가 내 땅이야. 그리고 네 것이기도 하지. 네 원대한 꿈과 함께 호흡할 수 있음이 기뻐.” 대륙 최고의 부자가 된 넷째 언니는 지도를 펼쳐놓고 이렇게 말했다. 그런 원대한 꿈이 없다고 말하면 대참사가 벌어질 것 같다. “공녀님께서 온전히 지배하실 겨울성이 너무나 기대된답니다.” 나를 섬기는 집사의 얼굴에도 웃음꽃이 피어올랐다. “네가 벨라투를 잇지 않겠다면, 내일 아침 내 심장은 멈춰 있을 거야. 그래도 괜찮겠니?” 원래 후계자가 되어야 할 첫째 언니는 목숨으로 나를 협박했다. 그리고 이게 제일 문제였다. 어쩐지 원작보다 더욱 강해진 아버지의 입가에 스산한 미소가 피어올랐다. “독립? 해보거라. 그 땅에 개미 한 마리 살려놓지 않을 테니.” 네가 내 품을 떠나 독립할 수 있을 것 같더냐……. 라며 흉폭한 눈동자로 나를 노려본다. 이상하다. 뭔가 아주 많이 잘못되었다. 나는 그냥 최선을 다했을 뿐인데.",
