        "synopsis":  "학창 시절 유명한 선남선녀였던 유진과 준우, 5년이 지난 지금 서로 역변한 채 재회했다? 성인이 된 유진은 남에게 말하지 못할 비밀을 품은 채 버추얼 스트리머로 은둔 생활을 하고 있다. 5년 전 여신으로 불리던 모습과 다르게 고도비만으로 역변한 것! 진짜 모습을 숨기며 시청자들에게 사랑받지만, 어느 날 의문의 시청자가 나타나 유진의 실체를 폭로하겠다. 협박하게 되고 유진은 그를 막아보려 하지만 일은 점점 꼬여가는데.. 유진 눈앞에 나타난 이태원 드랙퀸 ‘체셔’ “어디로든 가자, 하이힐이 이끄는 곳으로.” 체셔를 따라 드랙퀸 바 라마르에 입성하게 된다. 사실은 그가 자신의 첫사랑 준우일 거라 상상조차 못한 채로. 과연 둘은 역변한 서로의 모습을 딛고 성장할 수 있을까.",
