        "synopsis":  "평생을 믿어온 자에게 배신당했다. 인생이 송두리째 거짓말이었다. * * * 아버지만을 위해 살아왔다. 아버지의 복수를 위해, 기꺼이 모든 고통을 감내했다. 뼈를 깎는 고통 속에 훈련한 끝에, 최고의 암살자가 되었다. 평생을 믿었는데. 평생 아버지만을 위해 살았는데. 아버지를 위해, 사람까지 죽였는데. 그 아버지가, 아버지가 아니라니. 내가 죽인 사람이 내 진짜 \u0027아버지\u0027라니. * * * 평생을 한 악마에게 속아 친아버지를 죽인 나는, 그 악마가 내민 독주를 마시고 죽었다. 분명히 그랬을 터였다. 그런데, 죽은 게 아니야? 눈을 떠보니 몸은 작아져 있었다. 어린 시절로 돌아간 것이었다. 어찌 된 영문인지는 알 수 없었지만, 이것은 하늘이 준 기회. 평생 기만 당하고, 이용 당하고, 쓰임새를 다하자 버려버린 그 자를 벌할 기회. 결심했다. 나를 속인 대가는, 꼭 목숨으로 받아내고 말겠다고.",
