        "synopsis":  "이 세계가 전생에 내가 읽었던 바로 그 소설 속이라는 걸 깨달았다. 원작에서는 내 위치의 인물이 북부 공작가의 ‘장남’이자 당당한 후계자였는데, 웬일인지 지금의 나는 ‘장녀’로 살아가고 있다. 심지어 부모님은 나보다 내 남동생만 감싸고, 후계자 자리도 동생에게 돌아간 상태다. 전생에서도 K-장녀로 고생했는데, 여기서도 또 장녀라니! 이쯤 되면 진짜 장녀 숙명 아닌가? 이제 더 이상 가족들의 애정 따윈 바라지 않는다. 그 대신 충성스러운 신하도, 전설의 정령도, 그리고 원작에서 장남이 독차지했던 후계자의 자리까지 모든 걸 내가 되찾을 거다! 원작의 여주인공 \"네시아\"가 가졌던 것까지 전부, 이번엔 내 걸로 만들겠어! ...그런데 네시아, 이 아이는 왜 자꾸 나한테 호감을 보이는 거지?",
