        "synopsis":  "내 이름은 코코. 하얗고 복슬복슬한 털이 아주 멋진 강아지죠. “다음 생이 있다면 부디 언니 딸로 태어나 줘. 응?” 언니와 행복한 견생을 보내고, 무지개 다리를 건넜는데. \u0027헉, 내가 죽은 후에 언니가 맨날 울기만 하잖아!\u0027 안 돼! 우리 언니의 행복한 삶은 용감한 강아지가 지킨다! …그렇게 무지개 다리를 다시 건너, 언니네 가문에 다섯 살배기 입양 딸로 환생했다. 그런데 언니랑 친해지는 게 도통 쉽지가 않다. “사람 만나는 거 피곤해서 싫어. 조만간 저택의 문을 아예 닫을 거다.” 나는 급하게 짤따란 손을 들었다. 그러고는 그릴 수 있는 것 중에 가장 커다란 원을 그렸다. “나 이따만큼 강해요!” 그러니까 언니, 다시 나랑 친하게 지내 주면 안 돼? * ……언니에게 강아지라고 정체를 밝힐 수도, 친해질 수도 없어서 침울해진 것도 잠시. 나는 전직 용감 강아지, 현직 계략 어린이니까! 언니와 가족들을 열심히 공략해서 ‘진짜 가족’이 될 거야. “원하는 게 있다면 말해 보거라. 위대한 영물을 구했으니 마땅히 보상을 해 주마.” “……세 번째는요, 나랑 공놀이도 해 주고요, 네 번째는요, 나랑 같이 수영 놀이두 하구요, 다섯 번째는요, 나한테 고구마도 많이 주고요, 여섯 번째는요, 주방에서 나랑 같이 고구마 케이크도 만들구요, 그리고 일곱 번째는요, 절대 못 먹게 했던 초코도 먹어보고 싶구요…….” “공 한번 세운 김에, 나한테 싹 다 뜯어 보겠다고……?” “네!” “……야망이 넘치는 녀석이로군.” 언니의 아빠한테 똑똑하게 말대꾸도 해서 눈에 띄기까지! 그렇게 차근차근 언니, 그리고 언니네 가족들과 친해지고 난 뒤. 드디어 내 진짜 정체를 밝히는 날이 왔는데. “우리 코코, 언니랑 백 살까지 사는 거야. 알겠지? 약속.” “……딱히 네가 좋아서 그러는 건 아닌데, 스무 살 넘으면, 그, 야, 약혼도 하자. 뭐, 절대 널 좋아해서 그러는 건 아니니까. 오해하지 마.” 언니와 가족들, 소꿉친구까지 분리 불안이 너무 심한 것 같다. 그런데 사실, 나……. 열 살이 되면 강아지별로 다시 돌아가야 하는데?",
