        "synopsis":  "최고의 권력을 지닌 테제 공작가와 세상 모든 부를 그러쥔 오하라 백작가, 둘의 결합은 이보다 더 완벽할 수 없었다. 절절한 사랑이 없다는 것만 제외하면. “에반젤린 오하라는 준비된 공작부인입니다. 이제 와 다른 여자를 찾기도 번거로울뿐더러 그녀만큼 잘해낼 거란 보장도 없지요.” 데카르노에게 있어 그녀 이상의 공작부인은 없다. 그러니 겨우 파산쯤이야, 그 정도는 충분히 감수할 만했다. 하지만 그녀는 아니었다. “이제 그만뒀으면 해요.” “……파혼이라도 하자는 건가?” “네.” 지금껏 가져온 모든 것을 내어놓고 맨몸으로 나선 에반젤린. 모든 것을 내려놓았기에, 그 남자도 놓을 수 있었다. 홀로 가져왔던 마음까지도. “저는 각하를 좋아했어요.” “…….” “설마 하니 제가 공작부인 자리만을 탐냈다고 생각하셨던 건 아니겠지요?” 좋아했다면서 어떻게 이렇게 쉽게 떠날 수 있는 건지. 이해가 안 되다 못해 속이 들끓는 데카르노. 갈수록 꼬여가는 일도, 복잡해지는 머리도, 전부 그 여자 때문이다. 결국 모든 것을 제자리로 돌려놓는 수밖에. 필사적인 홀로서기에 나선 에반젤린을 찾아 나선다. “당신 살아남겠다며. 나 같은 인간 정도는 못 참을 것 없잖아.”",
