        "synopsis":  "난생 처음 보는 화려한 마차, 성인지 집인지 모를 대저택. 시골 촌구석에서 아빠와 오붓하게 지내던 나의 일곱 살 인생은 대부호 트라벨 백작이 집 나간 차남을 찾게 되며 달라졌다. 우리 아빠가 귀족이라고? 나한테 부자 할아버지가 있었다고?! 친척들은 6년 만에 어린 딸과 함께 돌아온 아빠에게 뜨거운 환영…이 아닌 싸늘한 눈빛만 쏘아댔다. 그때, 머릿속에 이상한 장면들이 폭우처럼 쏟아졌다. - 베리, 친척들을 조심해야 해. 트라벨은 가주 후계자 자리를 노리는 짐승들의 소굴이거든. - 베리 아가씨! 레이탄 도련님께서 전사…하셨다는 소식이……. 일곱 살, 열 살, 열여섯 살, ……. 모두 나였지만, 내가 모르는 기억들. 그리고 그 기억 속에서 아빠는 허무한 죽음을 맞이했다. *** 설마, 이게 진짜일 리 없어. “집사장님, 최근에 폭삭 망할 잉크사 주식을 다량 사셨습니까?” “그건 절대 안 망한다고……. 예? 제가 주식을 산 걸 어떻게?” 끄악! 이것도 다 맞잖아. 이 기억이 진짜라면, 이번에는 반드시 아빠를 살리고 말거야. 혼자만의 힘으로는 아빠를 살릴 수 없다. 가장 큰 뒷배가 되어줄 조력자가 필요한데…. 물론 나만 아는 보석이 하나 있지-. 지금은 진흙 묻은 돌멩이처럼 보여 견제받을 일도 없는. ‘테온 필 이그셀로나 황태자.’ 내 첫 번째 계획은 어린 그를 우리 편으로 만드는 거다.",
