        "synopsis":  "영웅 안데르트. 스스로를 희생해 대전쟁을 끝마친 위대한 검사. 희대의 영웅 중 한 명. ...이지만 실상은 죽은 남동생의 신분을 사용한 남장 여자. 그게 바로 나였다. 그런데. \"어?\" 죽은 후 4년이 지나서 되살아났다? 가진 것이라고는 몸뚱아리뿐이니 먹고살기 위한 길은 단 하나. 하녀. “어떤 저택에서 일하고 싶으시죠?” “둘이 일하다 하나 죽어도 모를 만큼 힘들고 고약한 저택.” “어떤 고용주를 원하시나요?” “고용인을 쥐어짜는 악독한 고용주.” 그래야 일할 사람이 나밖에 없어서 잘리지도 않거든. “…….” 면접관은 미친X을 감상하는 시선으로 나를 바라봤다. 그래도 상관없다. 이곳에서 나는 새롭게 시작할 것이다. 영웅 안데르트도, 죽은 남동생도 아닌. 하녀 데이지로.",
