        "synopsis":  "\"우리 헤어지자.\" 남자 친구에게 호구짓 당하고, 가족들에게 돈만 뜯기던 이샤엘. 심한 핍박을 견디지 못해 죽음에 이르게 되었을 때 이샤엘은 깨닫는다, 자신이 두번의 환생을 겪었음을. \"이전과 같이 살지 않겠어, 난 이제 새 인생 살러 갈 거야!\" \u0027…라고 말했는데 어떻게 집에서 독립하지?\u0027 독립에 대한 고민이 쌓여갈 때쯤 공무원으로 일하는 이샤엘의 눈에 띈 것은… \u0027신혼부부 타운 하우스 특별 무상 공급 정책\u0027! 그렇게 타운 하우스를 얻기 위해 남편 후보감들을 찾던 중 의외의 인물이 이샤엘에게 다가온다. \"저와 결혼해 주시겠습니까?\" \u0027제국 최고의 기사 딜런 경이 왜 나에게 청혼을...?\u0027 과연 이샤엘은 새 인생도, 새 가족도, 새 행복도 얻을 수 있을까? -- *매주 수요일(화요일 22시)에 연재 됩니다.",
