        "synopsis":  "로판 소설에 빙의했다. 이름조차 등장하지 않는 엑스트라로. 이게 바로 엑스트라 빙의물! ‘내가 소설 속 주인공이 되었구나!’ 빠른 깨달음 후 주인공의 삶을 즐기며 소설 속 진남주와 서브남, 흑막까지 모두 가까워졌다. 다들 날 좋아하는 거 같은데, 누가 내 남자가 될 건지 확신이 안 섰다. 그래서 대놓고 물어봤다. “루치, 나 좋아해?” “왜 그런 착각을 했지?” 루치가 황당하다는 듯 물었다. 소설 속 진 남주는 내 남자가 아닌가 보다. “해리슨, 나 좋아해?” “그런 소리 함부로 하는 거 아닙니다.” 해리슨이 정색하며 말했다. ……소설 속 서브남도 내 남자는 아닌가 보다. “데미안, 나 좋아해?” “제가 당신을 좋아했으면 좋겠습니까? 좋아해 드릴까요?” 데미안이 한쪽 입꼬리를 한껏 올리며 물었다. 비웃음까지 당할 줄은 몰랐다. 소설 속 흑막도 내 남자가 아니었다……. 난 진짜로 엑스트라였던 거다. 왜 이제야 깨달았지? 허무했지만 늦게라도 정신 차려서 다행이었다. 이제 내 분수에 맞게 내 남편감이나 찾아야겠다. “돌아가서 내 신랑감이나 찾으려고.” 날 좋아하지 않는다는 세 친구에게 떠난다고 알렸다. “뭐, 신랑감을 찾아?” “이건 정말 예상하지 못한 말이군요” “그게 무슨…….” 누가 보면 셋 다 날 좋아하는 줄 알겠다. 그런 거 아니면서. ‘흥, 누가 또 속을 줄 알고?’ 난 이제 이들의 행동에 착각하지 않을 거다. “나 바빠, 안녕!”",
