        "age":  "RATE_15",
        "finished":  false,
        "favorites":  64687,
        "episodes":  73,
        "synopsis":  "전설의 섬 제주 신화를 모티프로 한 판타지 액션 웹툰. 대재앙 이후. 세계는 작은 소부족으로 나뉘어 살아가고 있다. 각 부족에는 ‘힘 있는 자’라 불리는 신비한 능력을 가진 사람들이 있는데 그들은 부족의 공격력이자 방위력이다. 오랜 기간 소부족 사이에 크고 작은 전쟁과 갈등이 있었으나 ‘힘 있는 자’들이 나서서 서로를 침략하지 않기로 약속을 맺어 평화의 시기가 지속되었다. 그로부터 100여 년 후. 북부의 소부족이 스스로를 ‘무리를 이끄는 나라’라 칭하고 ‘국가’를 건설한 뒤 무력으로 소부족들을 복속시키기 시작한다. 소부족들은 식민지가 되는 한편 아이들을 빼앗긴다. 아이들은 ‘무리를 이끄는 나라’ ‘싸우는 자’가 되기 위한 혹독한 교육과 훈련을 받는다. 그리고 식민지 정복 전투에 투입된다. ‘싸우는 자’들은 ‘힘 있는 자’가 두 명이나 있는 ‘산부족’를 제압하고 파죽지세로 주변 부족을 무릎 꿇린다. 그들은 ‘들부족’과의 전투 중에 파괴의 힘이 잠재된 소년 가로와 ‘힘 있는 자’인 가로의 엄마를 포로로 삼고 들부족을 굴복시킨다. ‘무리를 이끄는 나라’의 막내 왕자이자 정벌 전쟁에 앞장선 전사인 모흔은 \u0027싸우는 자’들과 가로를 이끌고 태초의 섬을 점령하러 떠난다. 풍랑을 만나 좌초하지만 결국 태초의 섬에 다다른 그들은 그곳에서 ‘태초의 부족’을 만난다. 평화로운 태초의 섬에서 자신들과는 전혀 다른 사고방식과 생활 문화를 가진 이들과 생활하며 모흔과 ‘싸우는 자’들, 가로는 서서히 변하기 시작한다. 한편, ‘무리를 이끄는 나라’에서는 ‘고대의 힘(폭약)’ 개발에 성공하고, 이에 왕자 카이탄이 폭약을 싣고 군대와 함께 태초의 섬을 향한다. 포탄을 쏟아 부으며 태초에 발을 디딘 이들은 침략 전쟁을 시작한다. 태초의 부족 ‘신의 역사를 기억하는 자(심방)’은 ‘궤네깃또(신)’을 소환하여 맞서 싸운다. 그리고 모흔과 ‘싸우는 자’들은 본국에 맞서 태초의 섬과 태초의 부족을 지키는 싸움을 시작한다. 태초의 섬에서 제국과 식민, 기술과 정신, 침략과 평화, 경쟁과 협력의 치열한 대결이 펼쳐진다. 《신들의 섬》 시즌 1_1부 \u003c운명\u003e_2부\u003c나선형\u003e_3부 \u003c선택\u003e",
