        "synopsis":  "이세계 최강자 미하엘이 세나 앞에 서면 골든 리트리버가 된다? 어느 날 지하실에 던전으로 통하는 문이 열리고 한 남자가 찾아왔다. “여기선 기쁜 일이나, 슬픈 일이 생길 때마다 치킨을 먹어요.” “아가씨… 부디 저를 하인으로써 거두어 주십시오.” 치킨 먹였더니 하인 되겠다고 하는 남자, 감당 가능? 엎친 데 닥친 격 내가 이세계 대마법사의 후손이라고? 오히려 좋아하는 남동생과 연이은 고백공격에 혼란한 세나. 그럼에도 불구하고 먹방은 계속된다. 치킨으로 시작된 인연, 이세계와 현실의 간극을 뛰어넘고 계속될 수 있을까? 매운맛 일상에 지친 당신을 위한 달짝지근한 던전 로맨스, 시작합니다",
