        "synopsis":  "격동의 19세기 말, 귀족 셸 가문 남작 부부가 살해되고, 부모의 죽음으로 큰 충격과 실의에 빠진 아들 \u0027막시밀리안\u0027. 장례식을 치르고 돌아온 날 어머니가 고용한 신비롭지만 수상한 가정교사 \u0027록산\u0027을 만나는데... 마법을 사용하여 자신을 위험에서 구한 그녀에게 점차 묘한 끌림을 느끼는 막시밀리안. 록산이 불멸자이며, ‘붉은 가슴’을 지닌 상대에게 영생을 줄 수 있다는 것을 알게 되고, 그녀에게 점점 더 빠져든다. 하지만 일련의 사건 속에서 집착하는 록산의 모습을 보며 그녀가 천사가 아닐 수 있다는 의심과 악마성에 대한 강한 거부감을 느낀다. 그럼에도 막시밀리안은 자신이 록산의 운명의 상대인 ‘붉은 가슴’ 임을 직감하고 그녀에게 향하는 마음을 멈추지 못하는데...!",
