        "synopsis":  "외모와 능력, 분위기까지 갖춘 완벽한 남자 호연우. 하지만 연애 상대로는 최악, 가벼운 만남만 추구하고 진지한 상대는 가차 없이 차버린다. 그걸 알면서도 홀리는 사람이 넘쳐 \u0027연우\u0027 대신 \u0027여우\u0027라고 불리는 그는 사실... 진짜 여우다! 여우 수인 \u0027호인족\u0027은 자신을 향한 인간의 마음에서 생명력을 얻는다. 그 감정이 깊고 클수록 더 좋은데, 연우는 왜인지 깊은 마음을 꺼리고 상대가 진지해지면 오히려 내친다. 질 좋은 생명력을 흡수하지 못한 연우는 결국 병에 걸려 쓰러진다. 이대로라면 1년 안에 죽을 것이다. 해결책은 단 하나, 마음의 그릇이 거대한 사람을 찾아내 깊은 사랑에 빠뜨려 그 힘을 얻는 것. 호인족 수장인 염화가 연우의 눈에 신력을 주입해 사람마다 가진 마음 그릇을 볼 수 있게 된다. 하지만 눈 빠지게 찾아 겨우 발견한 거대한 마음 그릇의 소유자가 남자라니...? 그것도 어깨 떡 벌어진 유도선수 출신 체대남, 무뚝뚝하고 철벽으로 유명한 고정인이라니! 헤테로 섹슈얼? 상대가 도저히 안 내켜? 다 필요 없다. 살고 싶다면 \"목숨을 다해 꼬셔라!\"",
