        "synopsis":  "성형외과 전문의 자격증을 딴 ‘도지의’는 군의관 대신 3년 동안 보건의료 취약지구에서 근무하는 ‘공중보건의사(공보의)’에 지원하고, 극악의 합격률에도 불구하고 공보의에 합격하여 쾌재를 부른다. 하지만, 그가 발령받은 섬 ‘편동도’는 열악한 인프라와 주민들의 진상으로 공보의 커뮤니티에서 가장 악명이 높은 섬… 1년만 버티면 섬을 나갈 수 있다는 희망으로 잘 버텨보자고 다짐하지만, 첫 근무부터 급성 심근경색 환자를 치료하는 호된 신고식을 치룬다. 도지의의 힘으론 해결하기 어려운 응급 환자들과 주민들의 무차별인 진상과 폭언, 레지던트 생활을 능가하는 정신적 스트레스, 그리고 ‘도지의’를 압박하는 주변 인물들까지… 지옥의 섬 편동도에서 과연 도지의는 ‘존버’할 수 있을 것인가.",
