        "synopsis":  "Q : 늑대랑 사자가 결혼해서 토끼를 낳을 수도 있나요? A : 헛소리 말고 발 닦고 잠이나 자라. …발 닦고 잠이나 자야 할 상황에 처해 버렸다. 아빠는 사자고 엄마는 늑댄데 난 토끼라니. 그것도 소설 속 전쟁의 발단이 되는, 엑스트라 토끼라니! 이대로 가다간 모두 죽는 것은 물론 엄마와 아빠 두 가문 전부 멸망해 버린다. ‘안 돼. 어떻게든 운명을 바꿔야만 해.’ 주먹을 움켜쥐며 분연히 일어섰지만…. “클로이, 오늘 저녁이 뭔지 아니? 바로바로… 토끼 고기란다!” 일단 우리 집 늑대들한테 정체를 안 들키는 게 먼저인 것 같다. * * * 토끼인 것만 숨기면 될 거라고 생각했는데, 더 큰 복병이 찾아왔다. 수인의 수많은 고유 능력 중 하필, 하필 “동정받기” 능력이라니. 이번 생도 틀렸어, 그렇게 생각했는데. “싸우는 거 아니다. 그러니까… 울지 마라, 제발.” 내가 걱정돼 전쟁까지 멈춘 엄마 아빠에. “말만 해. 원한다면 널 괴롭히는 이들을, 전부 죽여 줄 수도 있어.” 좀 과하게 내 편이 된 원작 남주까지. 이거 이거, 전쟁 막기가 너무 쉽다. 어쩌면 내 능력… 생각보다 유용할지도?",
