        "episodes":  33,
        "synopsis":  "육아물 악역 조연으로 환생했다. 귀여운 여주인공의 큰오빠에게 집착하고 매달리다 결국 여주인공에게 독을 먹이고 파멸하는 그런 찌끄레기 황녀로. 너네는 이제 내 쪽에서 사절이야! 그렇게 다짐하고 튈 준비를 했는데. 여주인공을 구해 버린 뒤 일이 제대로 틀어져 버렸다. \"언니를 건드리는 놈들, 세상 끝까지 쫓아가서 박살내버려.\" \"황실? 티타니아를 불행하게 만드는 무능력한 황실. 어찌 되든 무슨 상관인가.\" \"하하하하, 저 놈들은 날 미친개라 부르면서 왜 저리 머릿속이 비었대. 미친개가 사람 가려 물면 미친개인가?\" 지, 진정하세요, 여러분. 전 파도가 아름다운 바닷가 별장에서 꿈과 희망과 돈을 즐기러 떠날 거라서요! 여러분도 행복하세요! ...인 줄 알았는데. “…당신이. 정말로, 죽은 줄 알고, 저는…….” 나를 담은 그의 금안이 내가 읽을 수 없는 감정에 잠겨 넘실거렸다. 보는 것 만으로 익사할 것 같았다. “…끝없는 악몽을 꾸는 기분이었습니다, 티아.” 더는 제 앞에서 그렇게 사라지지 말아주세요, 간절하게 속삭이면서도. 어디로든 가지 못하게 옭아매듯 내 손을 움켜쥐는 그에게 나는 할 말을 잃었다. 거기다. “우리 오빠를 미워해도 좋아. 우리 아빠를 귀찮아해도 좋아! 그치만, 우리 공작가의 돈은 싫어하지 말아줘!” …공작가 보물이 다 들어있는 지하금고 열쇠를 대뜸 쥐어주는 귀염뽀짝한 여주인공님이며. “다 귀찮아? 그럼 형 대신 날 선택해. 귀찮게 공작 부인 같은거 하지 말고. 언제 어디서든 네 곁에 있을 테니까. 뭐? 개 같은 소리 하지 말라고? 왈왈으르렁컹컹!” 언제나 눈엣가시처럼 날 보던 여주인공 둘째 오빠까지 좀 이상해졌다. 너네 왜 이래?",
