        "synopsis":  "‘집착광공을 연기하는 BL 소설 속 남장 공작.’ 이 평범치 않은 문장의 주인공이 바로 나다. *** 르윈 드 베르웬. 소드마스터, 출중한 외모, 권세 높은 공작가의 주인. 완벽해 보이는 그에겐 한 가지 비밀이 있다. 바로 남장 여자라는 것! *** 그러던 어느 날, 물에 빠진 후 미친 황녀가 그녀에게 말한다. “언니가 가짜 집착 광공이 되어 주세요!” 여기는 피폐 BL 소설 속이니, 세계 멸망을 피하기 위해 원작의 집착광공 대신 수를 꼬셔 달란다. 그래서 계획대로 집착광공을 연기해 수를 꼬셨다. 그런데……. *** “사랑하는 척이라도 하세요. 안 그러면 당신이 사랑하는 그 사람을 죽여 버리고 싶을 거 같거든.” 내가 꼬시고 차 버린 ‘수’는 신제국의 황제가 되어 돌아왔고. “그대를 갖기 위해선 뭘 해야 하나? 전쟁? 학살?” 원작의 ‘집착광공1’인 적국 황제는 정말 미친놈이고. “너의 입맞춤 한 번에 난 내 모든 걸 바칠 수 있어. 이 심장도, 이 제국도.” 순진한 줄만 알았던 소꿉친구는 사실 원작의 ‘집착광공2’란다. \u0027...도대체 왜 찐 집착광공들이 내게 세상을 거는 거냐구!\u0027",
