        "synopsis":  "평범한 직장인이었던 내가 어느 날 하드코어 육성 시뮬레이션 게임 속 악역 조연 \u0027벨린다\u0027에 빙의했다? 주인공을 학대하고 비참한 죽음을 맞이하는 운명의 캐릭터. 하지만 악녀가 되었다고 주인공을 학대할 이유는 전혀 없지. 주인공을 학대하는 대신 잔뜩 확대해버리겠다 다짐했는데…! ‘자, 레오야. 아- 해볼까?’ [동기화 진행 중 오류가 발생했습니다. 벨린다 언어로 번역됩니다.] “입 벌려, 쥐밤톨.” 이놈의 망할 시스템이 내 입을 지옥의 주둥아리로 만들어버렸다. 그런데 어쩐지… 악녀 생활이 생각보다 잘 맞는다? “게을러빠진 것들. 내가 발 디딜 곳에 레드 카펫을 깔라고 대체 몇 번을 말하게 하는 거야!” “왕도에서 최고로 잘 나가는 파티세리에서 한정판 마카롱을 종류별로 사 오도록.” “구하기가 어려워? 멍청하긴. 가게 앞에서 노숙하면 되잖아.” 돈, 권력, 미모. 거기에 시스템 창까지 총동원해 벨린다에게 닥친 문제들을 해결했더니… “벨, 나와 결혼해 주지 않겠어?” “주인님, 주인님은 왜 날 좋아하지 않아?” “블랑쉐 님, 당신은 이 흑백 세상의 유일한 예외입니다.” 게임에서 벨린다를 죽이던 후원자들의 태도가 돌변했다. 게다가. “상호 합의하에 대공 각하와 일정 기간 결혼 생활을 유지하다 이혼할 것을 제안드립니다.” 북부 대공이 보낸 계약결혼까지. 어쩌면 나, 패악 부리기에 재능이 있었던 걸지도?",
