        "synopsis":  "위장 잠입과 변신술의 귀재. 의금부 소속의 다모, 계서라. 자신의 진짜 신분을 숨긴 채 각종 사건을 해결해 가던 어느 날, 도성에 금혼령이 떨어진다. 세자빈을 셋이나 앞세운 세자 이 선이 네 번째 세자빈을 들인다는 것이었다. 조선 최고 불운의 아이콘으로 떠오른 세자의 금혼령으로 온 도성 안이 시끄럽던 어느 날, 서라는 세책방에서 곱상하게 생긴 한량 나리를 만난다. 시도 때도 없이 불쑥불쑥 나타나 서라의 일에 훼방을 놓는 이 남자. 뒷목 잡는 나날이 이어지던 어느 날, 그 남자가 말했다. “내 세자빈이 되거라.” ‘내’ 세자빈이라니? 한량의 정체는 바로 세자 이 선이었다. “세자빈들은 모두 살해되었다. 네 번째 세자빈으로 입궁하여 범인을 찾아다오. 사건을 해결하면 네가 원하는 건 무엇이든 들어주마.\" 거부할 수 없는 제안에 서라는 결국 네 번째 세자빈으로 입궁하는데... 서로의 이해관계가 확실한 계약 혼인이었건만, 시간이 지날수록 서라는 자꾸만 이 남자가 신경 쓰인다. “내가 너의 밤이 되어주마.” “저는 밤보다 낮을 더 좋아합니다.” “그러니 내가 너의 밤이 되어주겠다는 말이다. 더는 혼자서 울지 않아도 되는, 그런 밤.” 종잇장 위로 서서히 번지는 먹물처럼 스며든 그가 서라의 마음을 흔들기 시작한다. 이 혼인, 정말 이대로 괜찮은 걸까?",
