        "synopsis":  "내 이름은 아이카, 나이는 일곱 살. 특별한 게 있다면… 예지 능력이 있다는 것 정도? *** 사랑하는 엄마를 사고로 잃고, 삼촌에게 맡겨졌는데, 삼촌은 이 넓은 제국에서도 성격이 더럽기로 유명한 \u0027악당\u0027이었다. \"나한테 애 키우는 취미는 없어. 알아서 쥐 죽은 듯이 지내라?\" 엄마를 쏙 빼닮은 삼촌이 나를 냉대하는 건 마음이 아팠지만, 삼촌이 위험해지는 미래를 본 이상 이대로 물러날 생각은 없다. 삼촌한테 껌딱지가 뭔지 제대로 보여주겠어. …그랬는데, 어라? \"진짜 삼촌 버리고 갈 거야? 너 없이 삼촌 어떻게 살라고.\" 이젠 삼촌이 내 껌딱지가 되고, \"나는 너 외에 다른 생각은 할 수조차 없어.\" 순하기만 했던 소꿉친구가 집착하고, \"내게 다시 기회를 줄 수 있을까?\" 얼굴도 모르는 아빠까지 나타나 애원한다? 구하겠다고 했지만, 이렇게까지 할 생각은 없었다고!",
