        "synopsis":  "제국의 수호자, ‘영웅’. 강산이 수없이 변하는 긴긴 시간, 영웅은 늘 황실의 명에 따라 제국을 지켰다. 마땅한 이름은 없었다. 사람들은 영웅이 실존하는지조차 제대로 알지 못했으므로, 명예도 칭송도 없었다. 영웅은 황실에 목줄 잡힌 개였다. 광룡 봉인을 끝으로 황가에 봉인되어 있던 영웅이 다시 눈을 뜬 건, 그로부터 10년이 지난 뒤였다. 결혼식장에서, 오늘의 신부인 레일라텐 공작가의 사생아 로샨느의 몸으로. 몸이 바뀌었는데도 어찌된 영문인지 영웅의 영혼에 귀속된 힘은 그대로였다. 어떻게 이런 일이 일어났는지는 영웅도 알지 못했다. ​“혹시 이거, 내 결혼식이야?” ​검과 마수도 없고, 시체도 피도 없다니! 무수히도 많은 죽음을 밟고 피비린내 나는 전장을 누비던 과거와는 달랐다. “세상은, 세상은 이렇게 다채로웠구나…….” ​처음 느껴 보는 평화에 감동의 눈물을 글썽거렸다. ​“왜 저래?” “몰라. 팔려 가는 결혼식 앞두고 미쳤나 봐.” 하녀들이 숨죽여 우는 로샨느를 미친 사람 보듯이 보며 소곤거렸다. 됐고, 일단 팔려 가는 이 결혼식부터 엎자! “오늘 결혼식은 취소야, 공작. 상대는 변태고 나는 변태를 좋아하지 않거든.”",
