        "synopsis":  "“난 여주들의 ‘제목’을 볼 수 있거든.” 회귀자, 환생자, 빙의자가 넘쳐나는 로판 세계. 하지만 메이는 그 어느 쪽도 아니다. 그저 평범한, 지극히 평범한 ‘로판 원주민’일 뿐. 회귀의 기억도, 빙의자의 사명도, 환생자의 능력도 없는 순도 100%의 엑스트라다. 그럼에도 메이에게는 단 하나, 아주 희한한 능력이 있었으니… 바로, 로판 여주들이 빙의된 책의 ‘제목’을 볼 수 있다는 것! 그것도 단순한 제목이 아니라, 책의 내용 전체가 친절하게 담긴 초장문 스포일러형 제목을! 메이는 그 능력을 숨긴 채 조용히 살아왔다. ……사랑하는 여동생의 몸에 설은채라는 로판 여주가 빙의하기 전까진. 어떻게든 여동생을 되찾기 위해 방법을 찾던 그녀는 우연히 만난 ‘스승님’에게서 믿기 힘든 해답을 듣게 된다. “빙의자를 쫓아내는 방법은 단 하나. 그 빙의자의 남주를 먼저 꼬시는 것.” …근데 잠깐. 설은채의 남주가 누구라고? 공략 가능성 0.000001%의 폭군, 리하임 엘리브튼?! 수많은 로판 여주들이 그를 유혹하려다 실패해, 빙의한 몸에서 쫓겨났다고 한다. 회귀도 없고, 빙의도 없고, 환생도 없는 그저 엑스트라인 그녀가 리하임을 꼬실 수 있을까? 사랑하는 동생을 되찾기 위해 메이는 폭군의 심장을 흔들기로 결심한다.",
