        "synopsis":  "“경 공자… 살아 있으셨군요…” 오 년 전에 죽은 줄 알았던 정혼자가 살아 돌아왔다. “네, 살아 있습니다. 당신을 죽이기 위해서.” 나를 담았던 눈동자에, 오직 증오만을 담은 채로. . . . 송양의 황제이자 \u0027서화\u0027의 부친인 선문제는 황위를 지키려 형제들을 몰살시킬 만큼 의심이 많은 자이다. 그는 충신 백종의 아들 \u0027원의\u0027를 사위로 맞으려 했으나, 간신의 무고로 하루 아침에 원의의 가문은 반역의 누명을 쓰게 된다. 서화는 원의를 구명하려 애썼지만, 황명에 따라 구금된 채 무력하게 정인의 가문이 숙청되는 것을 지켜볼 수밖에 없었다. 결국 저잣거리에 원의가 효수되었다는 소식을 들은 서화는 그의 뒤를 따르려 했으나, 실패한 채 산송장과 다름 없는 삶을 이어나간다. 선황의 뒤를 이어 실권을 잡은 오라버니 유정은 평소 서화를 시기하던 탓에, 남은 원의의 가족인 원의의 어미와 누이의 목숨을 빌미로, 그녀를 비천한 사내에게 강제로 시집보내며 그녀의 삶을 진흙탕 속으로 밀어 넣는다. 그로부터 5년 뒤, 폭정을 휘두르던 유정을 치기 위해 반란이 일어나고, 죽은 줄 알았던 원의는 영웅이 되어 궁에 돌아온다. 재회의 기쁨도 잠시, 자신을 죽이러 왔다는 옛 연인의 선언에 다시 무너져 내리는 서화. 반란이 성공하자 서화는 유정의 협박으로 백두교에 상납금을 냈던 이력이 문제가 되어 관노로 전락한다. 자신의 가문을 멸망시킨 남자의 딸, 서화를 증오하면서도 끝내 그녀의 목을 베지 못한 원의는, 서화를 제 가문의 노비로 달라 새 황제에게 청하는데... 모든 것을 잃고 바닥까지 추락한 서화와 자신의 가문을 멸망시킨 여자를 여전히 사랑하는 원의. 그녀를 죽여야만 완성되는 복수 앞에서 자꾸만 길을 잃은 남자의 어긋나는 마음. ‘이토록 증오스러운 당신을, 나는 왜 죽이지 못하는 겁니까.’",
