        "synopsis":  "내 이름은 레오노라 하차니아. 이름부터 하찮은 엑스트라 악당의 딸이지만 권력욕이 대단하죠. 하차니아 가문을 원작처럼 하찮게 둘 수 없어! “좌로 구름미다, 씰씨!” “실시!” “우로 구름미다, 씰씨!” “실시!” 잉크를 칠해 만든 선글라스를 뽐내며 나는 바락바락 목청을 높였다. “에노끄 훈뇬병, 울지 안씀미다!” 나와 눈이 마주친 마음 약한 셋째가 찔끔 놀라 삐죽 나온 콧물을 들이켠다. “우, 울지 않습니다!” * * * 성공했다. “원래 이렇게 약했던 건가? 쓰레기같군.” “크억! 사, 살려줘!” “형, 괴로워보이니까 빨리 죽이는 건 어떨까? 그게 저 사람에게는 더 좋은 일일 거야.” 남주 콧김에도 날아가는 촛불 엑스트라였던 오빠들이 세계관 최고 악당 형제가 되었다! 어설픈 악당 아빠가 살짝 난관이었지만, “리니, 또 무슨 악독한 짓을 계획하고 있는 것이냐…….” “쿠쿡, 아니다. 내 딸다운 못된 짓을 계획하고 있는거로군. 아주 좋다.” 이중인격 빌런으로 개조시켰다. 쿠쿡. 움화화! 좋아. 원작 정보를 이용해 재산도 불렸겠다, 가문도 하찮지 않게 만들었겠다! 빨리 시한부 육체를 탈피해 제대로된 빌런의 삶을 즐겨 보려고 했는데- “공녀가 다정한 사람이라는 거, 알고 있습니다. 그러니 내게만 상냥하길 바라는 건 욕심이겠죠.” 아무래도 가문을 위해 부활시킨 인간 병기가 조금 고장 난 것 같다. “하지만 상냥해질 대상이 없어지면…….” 그의 손에서 피어오른 새빨간 불꽃이 세계 지도를 불태웠다. “나에게만 상냥해질 수도 있지 않을까요?” 마치 세계 전체를 잡아먹을 듯이.",
