        "synopsis":  "\u003c스킬 [금쪽이 상태 알림창]을 획득했습니다! 당신의 도움이 필요한 아이의 상태를 보다 정확하게 파악할 수 있습니다.\u003e * 에디스 이레네 브뤼셀에게는 한 가지 비밀이 있었다. 그녀가 바로 빙의를 경험했다는 사실이다. 그녀는 어느 날 갑자기 에디스가 되었다. 그것도 아예 다른 시대, 이름조차 처음 들어 보는 낯선 나라에서! 게다가 남들에게는 보이지 않는 이상한 능력과 함께. 돌아가기 위해 에디스가 선택한 것은 천재 마법사인 공작과의 계약결혼. “나와 결혼하겠습니까?” “네! 좋아요!” 그런데. “웬일이야. 정말 자기가 공작가의 안주인이라도 된 줄 아는 거 아녜요?” “브뤼셀이라. 누구 그 가문에 대해 들어 본 사람 있어요?” 귀족들이 몰락 가문 출신이라고 왕따를 시킨다. \u0027오히려 좋아!\u0027 긍정적으로 생각하고 혼자 다니는데, 사교계 뒤편에서 힘들어하는 아이들과 자꾸 마주친다. \u003c 스트레스 : 130/100 [!!위험!!] \u003e [금쪽이에게 적절한 조치가 필요합니다.] “자작 부인, 아이의 손을 잡아 주시겠어요?” 도저히 두고 볼 수 없어 나섰더니 어느 순간 \u0027해결사\u0027로 소문이 났다. \"공작 부인, 다음주 중에 한번 따로 뵈었으면 하는데요.\" \"저도요. 혹시 저희 저택에 와주실 수 있을까요?\" 사교계에서 왕따였던 내가 초대 순위 1위가 된 건에 대하여. * 겨우 달라진 분위기에 적응하는데, 이번에는 남편이 이상하다. \"그런 걸 보통 좋아한다고 말합니까?\" \"아무래도 그렇지 않을까요?\" \"그렇다면 내가 좋아하는 건 당신이 됩니다만.\" 세상에, 대체 누가 고백을 그렇게 해요!",
