        "synopsis":  "인간처럼 보이지만, 인간보다 강한 능력을 가진 존재, 씰. 세상 곳곳에 잠들어 있는 그들은 자신을 깨운 자에게 이름을 부여받고, 오직 그 사람을 지키기 위해서만 행동하는 신비로운 존재이다. 작은 어촌 마을의 평범한 요리사였던 줄리탄은 씰과 조우하고, 그녀의 붉은 눈동자와 닮은 이름을 선물한다. \"제 이름을 말해주세요.\" \"...카넬리안.\" \"고결한 영혼의 계약자, 씰 카넬리안이 맹세합니다. 기사 줄리탄 님을 저의 주인으로 모시겠습니다.\" 하지만, 줄리탄은 자신의 평범한 능력으로는 카넬리안의 비범한 능력을 감당할 수 없다는 사실을 깨닫는다. 결국 그는 그녀의 강한 능력에 걸맞는 새로운 계약자를 찾아주기 위해 긴 여정을 시작하는데...",
