        "synopsis":  "미래의 흑마법사 교주, 암흑길드 수장, 싸이코패스 황제가 될 아이들의 악독한 보육원 선생이 되었다. 괜히 얽히지 말고 보육원에서 슬쩍 튈까 했지만, “우릴 버리고 가는 건가요……?” 불쌍한 꼬마 악당들을 지극정성으로 키우기로 했다. * * * “이 잘난 얼굴을 조금이라도 더 봐야 저한테 승산이 있을 것 아니에요.” 드레스를 벗어 던지고 말끔한 제복을 입은 마샤는 자기애가 강한 어른으로 자라 있었다. “선생님은 내가 위험할수록, 내게 눈을 떼지 못할 거예요. 가엾고 불쌍한 것들에 약하니까.” 거칠고 사납기로는 제국 제일이지만, 한나에겐 한없이 부드러운 제레미. 하지만 그의 애정 방식은 어딘지 조금씩 엇나가고 있었다. “당신이 원하는 건 뭐든 들어드릴 생각이에요. 그게 뭐든, 무엇 때문이든. 대신 선생님은 제 곁에 있어 줘요.” 황제가 된 이안. 그리고 여전히 속을 알 수 없는 그의 행동들. 이안은 정말 호구일까? 아니면 다른 뜻을 숨기고 있는 걸까. 이것 참. 제대로 키운 건 맞는 것 같은데, 조금 문제가 생긴 것 같기도? “난 그대와 하고 싶은 불순한 것들이 많은데.” 이보세요, 교황님. 당신까지 왜 이래?",
