        "synopsis":  "1948년, 이름처럼 자유롭지만은 않았던 해방기. 조선 최초의 속옷 가게 ‘경성 란제리 의상실’에서 손님들을 속사정으로부터 해방시켜주는 디자이너 ‘해란’은, 사실 보름밤마다 흑영(黑影)의 지시로 반민족행위자를 암살하는 ‘살수’다. 이중생활 중인 해란은 어느 날 자신을 추격하는 경찰 ‘석주’에게 쫓기다가 누군가에게 정체를 들킨 채 쓰러지는데…. 난생처음 느껴보는 따스한 손길. 상처를 치료하고, 저를 보호해 준 그날의 은인은 누구였을까? 평소 살수의 삶에서 벗어나기 위해 흑영을 추격하던 해란은 마침 그날의 은인에게서 흑영의 흔적을 찾게 되고. 한편, 흑영은 살수를 곁에서 감시하기 위해 유학파 디자이너로 위장한 채 경란실에 잠입한다. 그러나 두 사람은 서로에게 사적인 마음을 품고 마는데…. ‘우리 관계는… 새장을 탈출할 열쇠였을까. 서로를 옭아맬 족쇄였을까.’ 그 시절, 각자의 새장에서 탈출하려 서로의 꼬리를 쫓는 세 청춘의 삼각 해방 로맨스.",
