        "synopsis":  "잡종으로 태어나 외할아버지에게 학대당하다가 죽었다. 내가 가문의 이능을 발현하지 못한 쓸모없는 아이였기 때문에. 기억을 가진 채 과거로 돌아왔지만, 선택지는 과거와 그리 다르지 않았다. 이대로 살다가 전생과 똑같이 학대당해 죽거나, 나를 끔찍하게 싫어하는 아빠를 찾아가거나. \u0027다시 죽는 건 싫어.\u0027 결국 나는 나를 끔찍하게 증오한다는 아빠를 찾아갔다. 흑표 가문의 딸이라는 걸 증명할 수 있는 로켓 하나를 손에 꼭 쥐고서. \"제가……, 제가 여기서 지낼 수 있게 해 주세요.\" 내가 요청한 건 성년이 될 때까지의 보호. 혼자 살 수 있는 나이가 되면 폐 끼치지 않고 나가서 살 생각이었다. 나는 아무짝에도 쓸모없는 아이였으니까. 그런데……. \"사랑하는 내 딸, 너를 건드리는 놈이 있다면 당장 그놈의 숨통을 끊어 버릴 거다.\" 나를 싫어하는 줄 알았던 아빠는 내게 너무 상냥하고, \"야, 페르디. 너 자꾸 티엘 번쩍번쩍 안지 말라고. 요맘때 여자애들은 아주 섬세하게 대해 줘야 한다고 했단 말이야.\" \"그 멍청한 이론은 또 어디서 배웠어? 티엘은 안아 주는 걸 좋아해.\" 무섭다고 생각했던 두 오라버니들은 나를 너무 좋아하는 데다. \"티엘, 네게 이 흑표 가문의 가주직을 넘길 생각이다.\" 친할아버지는 갑자기 내게 가주직을 넘긴다고 한다. 저기…… 다들 저 싫어하시는 거 아니었어요?",
