        "synopsis":  "수천억의 유산을 상속받은 도도백화점의 희대의 재벌 고양이, ‘도도’. 베일에 싸인 음모로 납치당해 죽을 위기에 처했다가 마녀를 만나 9등신 미녀 ‘나홍’으로 변신한다! 하지만 마법의 패널티는 너무나 가혹했다. [100일의 시간 제한, 그리고 9개의 목숨.] 할머니를 구하러 갔지만 이미 저택은 가짜 고양이가 차지했고, 위기에 처한 나홍을 구한 건 고양이 알레르기가 있는 보안요원 ‘백일’이었다. 나홍은 백일의 카드를 긁어대며 지름신 냥이의 본색을 드러내고, 백일은 그런 빈대 냥이를 길들이기 위해 폭군 집사를 자처하는데……! 하지만 나홍에게 백일은 단순한 인간 수컷이 아니다. 자신에게 \u0027나홍이\u0027라는 이름을 지어준 세상에 단 하나뿐인 나의 ‘소중한 집사’니까! “내 할머니와 내 집사 ‘백일’이는 무슨 일이 있어도 내가 지킨다냥!” 도도백화점 사장 \u0027설칠국\u0027의 수상한 움직임과 나홍의 목숨을 노리는 의문의 고양이 킬러 \u0027도준영\u0027의 등장까지! 과연 나홍이는 9개의 목숨이 다하기 전에 할머니를 구하고, 내 하나뿐인 집사 백일의 곁에 영원히 살아남을 수 있을까? 인간보다 더 인간적인 고양이의 상상초월 100일간의 생존 동거 로맨스!",
