        "synopsis":  "1레벨의 마력불능 연금술사 김시문. 지구가 멸망하던 그날. 등가교환만 성립하면 무엇이든 가능한 현자의 돌을 연성했다 \u0027원하는 모든 것이 가능하다고?\u0027 지금 원하는 것은 지구를 멸망시키고 동생을 죽인 저 원흉에게 한방 먹이는 것, 그리고, 마력 불능 따위가 없는 삶을 살아보는 것! 그렇게 후회만 가득한 생을 마무리한 줄 알았는데... 눈 떠 보니 11년 전으로 회귀했다? \u0027이번에야말로......\u0027 비참했던 마력불능자로서의 삶도, 앞으로 일어날 모든 불행한 일들도 모조리 뜯어고쳐 주겠어! 파트너인 현자의 돌과 함께 미래를 바꿔 나가는 시문의 여정을 지금 웹툰으로 만나보세요!",
