        "episodes":  68,
        "synopsis":  "어린 남주를 학대하는, 남주의 전 부인에 빙의했다. 원작대로라면 남주는 전쟁터에서 망국의 공주와 사랑에 빠져 그녀를 데려올 것이다! 남편이 공을 세우고 돌아오니 그제야 매달리며 패악을 부리는 원작과 달리, 나는 얌전히 이혼을 당할 생각이다. 어린 남편을 막냇동생 대하듯 잘 키워 전쟁터로 보내고, 그러는 김에 돈도 좀 챙기고, 영지도 잘 꾸려나갔다. 또 원작처럼 불치병에 걸려 죽기 싫어서 치료제도 개발했다. 이제 남은 건 이혼당하는 것뿐! *** 그런데 돌아온 꼬마남편, 아니 엄청 커버린 남편의 반응이 이상하다. \"내가 전쟁터를 구르는 동안, 부인은 도망갈 준비를 하셨군요.\" 그가 커다란 손으로 허리를 휘감으며 위험하게 웃었다. \"그새 바람이라도 난 겁니까?\" 예쁘게 올라간 입꼬리와 달리, 눈은 뜨겁게 불타고 있었다. 아니…… 저기, 나 이혼당할 준비 끝냈는데……. #선육아 후연애 #착각계 #키웠다가 잡아먹히는 여주 #여주 앞에서는 순진한 척 하는 대형견 남주",
