        "synopsis":  "김이영, 그녀는 대한민국의 평범한 공무원 시험 응시생이었다. 그것도 4년 반이 넘는 긴 시간동안 공부 끝에 합격한, 낙이라고는 짬짬이 소설읽는 것밖에 없는 정말 평범한 사람. 그러나 합격을 축하하기 위해 외식을 나간 날 교통사고를 당해 죽고, 자신이 읽던 현태판타지 헌터물에 빙의하고 만다. 그런 이영에게 집으로 돌아갈 수 있는 길을 제안하는 \u0027시스템\u0027. 그녀는 오로지 집에 돌아가서 배 따땃하게 지지고 귀여운 말티즈 켈베로스를 끌어안겠다는 일념 하에 수십 번씩 회귀하며 힘을 길렀다. 원작 속의 성좌들과 계약하고 수차례 죽어가며 원작 속의 \u0027탑\u0027을 공략하여 결국 마지막 층의 지배자, 탑의 주인을 처리하는 데 성공한다. 이제 남은 건 집으로 가는 것 뿐……, 인줄 알았는데! [오류로 인해 원래 세상으로의 복귀 대신, 작가의 신작에 빙의시켜드리겠습니다!] 필요 없어! 내가 바란건 내 스윗 홈뿐이었는데! 그게 그렇게 어려워?! 탑도 내가 없애줬는데?!?! 게다가, 로맨스 판타지라니! 이전 빙의에서도 로맨스의 ㄹ도, 아니, ㄹ의 한 획도 신경 안 쓰고 살았는데! 거기에 이전처럼 내 몸으로 책에 빙의한 게 아니라 책 속의 \u0027악녀\u0027에 빙의했다! 이 세계의 위협은 전혀 두렵지 않지만, 로맨스를 강제로 끌어내는 퀘스트는 걱정된다. 나, 집에 갈 수 있을까……?",
