        "synopsis":  "“빌어먹을!” 전남친 겸 상관 때문에 진급에서 떨어졌다. 노아는 참을 만큼 참았으나, 인내의 한계에 다다른 그녀가 할 수 있는 건 딱 하나였다. “계급장 떼고 한 판 붙자!” “그냥은 재미없으니, 이긴 사람 소원 들어주기 할까?” 그리고 두 사람은... *** “결혼 서약을 할 때 예물로 검을 나눠 가질까?” “그 검으로 중장님을 베어도 된다면, 기꺼이 하겠습니다.” “붉은 드레스가 입고 싶다고? 격하네, 내 신부...” “중장님 드디어 정신을 놓으셨습니까?” “그러고 보니 내 눈동자도 붉은데, 혹시 날 위해서?” “중장님의 피로 물들일 수 있다면야.” “그럼 오늘부터 한 방울씩 모아볼게.” “그럴 고생 마시고, 제가 단번에 죽여드리겠습니다.” “노아 너 정말 뜨겁고 격해...! 그런 건 침대에서 말해야지!” “그냥 첫날밤에 사망해 주십시오.” “그러면 부부 합장묘로 묻어 주라. 네가 죽을 때까지 기다릴게. 바다 수장 어때?” “저는 매장을 선호합니다만.” 노아는 레토가 했던 말을 몇 번이고 곱씹으며 치를 떨었다. 내가 왜 저런 놈이랑 그렇고 그런 사이가 되었던 거지? “정말 보통 미친 게 아니야...” 아무리 생각해도 얼굴과 몸 말고는 제대로 된 답이 나오지 않았다. “......” 그리고 그런 친구를 바라보는 아미의 시선은 싸늘하기만 했다. “너도 이상해.”",
