        "synopsis":  "거지노릇을 하며 고아로 지내던 천유옥에게 군악이라는 친구가 생긴다. 유옥은 군악의 동생 청아의 목숨을 구하고 군악은 그의 목숨을 구하면서 유옥은 군악을 목숨을 주어도 아깝지 않은 친구라고 여긴다. 천왕교에 함께 들어가게 된 두 사람은 패왕의 제자와 천왕교의 군사전인 천기원의 후계자로 자라게 된다. 지옥십관을 통과하며 암천혈왕이 된 천유옥은 백리군악의 흉계로 목숨을 잃을 뻔하지만 의부인 풍백의 목숨과 바꿔 살아남게 된다. 천왕교는 천왕곡에만 머물지 않고 천하를 호령하려는 천왕의 욕심과 그를 견제하는 세력으로 분산되지만 백리군악의 계책으로 천하를 향해 웅지를 펼치며 피를 뿌리기 시작하는데……. “암천혈왕, 혈사자가 명한다. 천왕율을 어기는 자, 피의 율법으로 다스릴지니!” 얽히고설킨 암계와 음모를 뚫고 천유옥이자 전무심인 그가 천하를 향해 호령한다!",
