        "synopsis":  "“야, 배고프냐?” 사흘을 쫄딱 굶은 내 앞에 말랑말랑한 흰 빵이 나타났다. 팔뚝만 한 빵을 그 자리에서 해치운 내게 악당이 비열하게 웃었다. “먹었으면 이제 대화를 해 볼까?” 빵 하나에 악당에게 인생이 저당 잡혔다. * * * 내게 빵을 준 남자는 악당, 그중에서도 길드장씩이나 해 먹고 계신다는 악당 두목이었다. 내 능력인 투시를 어떻게 알고 찾아와 이상한 거래를 제안했다. “난 밥을 주고, 넌 일을 하고. 밑지는 장사 아니잖아, 그지?” “따뜻한 곳에서 잘 수 있어? 때리면 안 갈 거야.” “물론이지. 쥐똥만 한 걸 왜 때려. 금화도 주마.” “좋아! 근데 그 주머니에 있는 빵은 안 먹을 거야? 나 줘.” 이러나저러나 나쁜 놈이긴 하지만 보육원 원장처럼 동냥시키고 밥을 굶기진 않으니 이편이 낫겠다 싶었다. 그래서 손을 잡았다. “신입. 볼 한 번만 만져 봐도 됩니까?” “한 번에 1브린(100원)이야.” “허어억 너무 싸지 말입니다! 제 월급을 다 드리지 말입니다!” “……장난인데.” 그냥 맡은 일만 다 하면 되는 줄 알았는데 길드원들의 애정이 이상하리만큼 과한 것 같다. * * * 처음으로 의뢰를 실패했다. 크게 다칠 뻔한 나를 두목이 구해 줬다. “두목, 나 아직 성공 못 했는데.” 나는 옆구리에 대롱대롱 매달려 가며 말했다. “그게 중요해? 어디 다쳤어, 안 다쳤어.” “……안 다쳤어.” “됐어, 그럼. 가서 밥이나 먹자. 배고프다.” 피도 눈물도 없다더니. 악당 두목이 이상해졌다.",
