        "synopsis":  "압도적인 실력의 S급 용병, 에리카. 그런 그녀를 졸졸 따라다니는 또 다른 S급 용병, 차우드. “에리카, 나랑 고정 페어 하자. 나랑 페어 맺고, 나랑만 해.” “왜 그렇게 나랑 하고 싶은 건데?” “열 받아서.” “……?” “네가 나 말고 다른 허접한 놈이랑 붙어 다닐 생각을 하니까, 열 받아서 잠도 안 와.” 동갑내기. S급 용병. 성격도 개망나니 같은 게 서로 비슷했다. 은연중에 동질감을 느꼈던 거 같다. 순식간에 친해진 걸 보면. “에리카. 내가 정말 갖고 싶은 게 있는데, 못 가져서 미쳐 버릴 것 같아. 남한테 빼앗기면 전쟁이야, 진짜.” “뭔진 모르겠는데, 왜 날 그렇게 노려보면서 말하냐? 내가 뺏었냐고요.” “네가 그럴 때마다 울고 싶어.” 세월이 흐른 뒤 에리카는 당황스러울 수밖에 없었다. “도, 도대체 왜 이러는 거야?” “말했잖아, 에리카.” 그가 나지막이 말했다. “남한테 빼앗기면 전쟁이라고.”",
