        "synopsis":  "Q. 믿었던 아빠가 엑스트라가 아닐 때의 심정을 서술하시오. A. 뭐, 뭐야…. 내 ‘지나가던 제국민 1’ 역할 돌려줘요…. 1년 365일 전쟁 중! 하루라도 바람 잘 날 없는 미친 세계관! 이곳에서 엑스트라로 태어났다는 건 축복이었다. “공주~ 일어나세용♡” “아고, 이뻐라 울 딸♡♡” 게다가 멋지고 다정한 아빠(제임스 브라운, 27세, 엑스트라)와 산골 마을에서 오순도순 살아가는 소박한 삶이라니, 최고다! ……라고 생각했는데. * * * “자, 그럼 보시져! 마침 등장한 저분이 바로! 제 아버지입니다! 널리고 널린 평민 남자들의 상징, 갈색 머리와 갈색 눈!” “…….” “요, 요리 보고 조리 봐도 지나가는 제국민 1에 불과하져. 산골 마을에서 어린 딸과 힘들게 나무 해서 먹고 사는 27살 미혼부예요.” 기사단장은 무심한 표정으로 나를 쳐다볼 뿐이었다. “…저어, 선생님? 저기여? 으앙!” 그 순간, 기사단장이 흠칫하며 검을 빼 들었다. 나는 본능적으로 돌아보았다. ‘…아빠?’ 아빠의 낡은 부지깽이 위로 푸른 기운이 일렁이고 있었다. 나는 눈을 비비고 다시 보았다. ‘저, 저게 뭐야?’ 다음 순간. 엑스트라 1의 상징이었던 아빠의 갈색 머리와 갈색 눈이…. 서서히 바뀌었다. “헐.” 누가 봐도 ‘나 주인공이야!’ 하고 외치는 눈부신 은발과 번뜩이는 푸른 눈동자로! ‘저, 저기요? 홀로 어린 딸을 키우는 산골 마을 27세 미혼부….’ ……제임스 씨? 이거 맞나요? “내 딸 내놔, 이 개자식아.”",
