        "synopsis":  "피폐 소설 속 마수로 변이하는 남주의 약혼녀에 빙의했다. 원작 초반에 죽는 시한부 악녀 역할이다. 그래서 어떡했냐고? 빛보다 빠르게 도망쳤다. 그리고 잡혔다……. 하지만 내 사전에 포기란 없다! 남주의 경계만 풀면 또 도망칠 수 있다는 생각에 열심히 노력했다. 남주가 악몽에 시달릴 때면 자장가를 불러주고 마수로 변할 것 같으면 열심히 위로해 저주를 누그러뜨리고 상처 입으면 치료해주고 적에게 공격당하면 함께 싸워주었다. 자아, 이제 정말 도망칠 시간! 그런데 남주의 상태가 이상하다. 심지어 원작 여주와 악역 황태자까지 내 주변만 맴도는데……? * * * 아슬란은 거울에 제 얼굴을 비춰보았다. 여기저기 꼼꼼히 돌아보며 피가 묻은 곳이 없는지 살폈다. “이 정도면 좋아하려나.” 거울 속엔 매력적인 남자 하나가 서 있었다. 참혹한 살육의 흔적은 온데간데없이, 완벽한 슈트 핏 아래 탄탄한 근육의 윤곽이 고스란히 드러났다. 아슬란은 자신의 외모에 신경을 써본 적이 없었다. 그에겐 길바닥 개미만큼이나 무가치한 일이었다. 비비안을 유혹하고 싶다고 생각하기 전까지는 말이다.",
