        "synopsis":  "\"Who am I?\" 프랑스 외인부대의 전설 \u0027강찬\u0027! 아프리카 전장에서 그를 상대한 자들은 공포와 경외를 담아 \u0027갓 오브 블랙필드\u0027 검은 땅의 신이라 불렀다. 하지만 수니파 추종 세력 SISS의 수뇌인 마살란 사살 작전에 투입된 강찬은 배후에서 날아든 의문의 총알에 전사하게 되고, 점점 감기는 시야 사이로 압도적인 열세에 자신을 믿고 따르던 동료들이 하나 둘 목숨을 잃어가는 것을 마지막으로 무기력하게 눈을 감는다. 그렇게 배신을 당해 죽음을 기다리고 있던 강찬은 의문의 힘에 의해 3년의 시간을 넘어 \u0027강찬\u0027으로서 대한민국으로 돌아오게 되지만, 그는 19살의 왕따를 당하는 또 다른 \u0027강찬\u0027이었다. 배신자의 복수, 환생에 얽힌 진실을 찾기 위한 강찬의 여정이 시작 된다!",
