        "synopsis":  "소설 속 남주들과 외딴섬에 갇혀버렸다. 그것도 19금 피폐 소설에 나오는 남주들과 말이다. 하지만 내가 빙의한 마거릿이란 캐릭터는 여주를 시기하여 괴롭히다가 곧 남주들에게 죽을 운명. 그러니 살아남으려면 일단 남주들에게서 도망가야 하는데... \"마거...릿?\" 남주 1의 손이 도망치려는 내 발목을 움켜쥐었다. 초장부터 내 계획은 망하고 말았다. *** 치가 떨릴 정도로 날 싫어하던 인간들이 섬에서 함께 지지고 볶는 동안 많이 변했다. “내 옆에서 떨어지지 마, 위험하니까.” “제발 널 돕게 해줘. 네가 어떻게 될까 봐 난 미쳐버리겠어.” “나 좀 봐줘, 응? 나도 좀 봐주면 안 돼?” 여주에게 집착해야 할 미친놈들이 내게 집착하기 시작한 것이다. 나는 그저 무사히 살아남고 싶을 뿐인데. 게다가 이 기묘한 열대의 섬은 우리가 미처 깨닫지 못한 깊은 비밀을 품고 있는 것 같다.",
