        "synopsis":  "“십 년간 오늘만을 준비했어. 그러니까 네가 이해해라.” 최강의 플레이어라 불리던 이수혁. 그러나 믿었던 친구의 배신으로 길드원들을 지키다 처참한 죽음을 맞는다. ···눈을 뜬 순간, 그는 무려 20년 후의 세상에 돌아와 있었다. 세상은 그의 죽음을 ‘사고’로 기억하고, 배신자는 이수혁의 명성을 등에 업고 승승장구하고 있었다. “이건···, 시우의 얼음꽃?” 사라진 줄 알았던 길드원들이 살아있을지도 모른다. 동료들을 되찾고, 배신자를 무너뜨리기 위해— “전과 똑같은 방법으로는 안 돼.” 더 빠르게, 더 강하게, 압도적으로 강해져야 한다. 그리고 그 힘을 얻기 위해 필요한 건 단 하나, 돈. 그가 이번 생에 선택한 길은 바로··· 스트리밍! 죽음을 넘어 돌아온 최강자 이수혁, 지금 방송 시작합니다.",
