        "synopsis":  "\u0027흔해 빠진 외모, 자작가의 사생아.\u0027 내세울 만한 배경은 없지만 비상한 머리 덕에 시녀의 신분으로 권세를 손에 쥔 레오나. 하지만 영원불멸할 줄 알았던 제국이 적의 침공에 무너진 순간, 그녀 역시 적병의 칼에 죽음을 맞이한다. 욕심 때문에 남을 해치고 권모술수를 서슴지 않았던 삶. 후회로 가득한 인생이었기에 죽음이 달가웠건만... 다시 돌아왔다. 갓 시녀로 입궁했던 그때로. 이건 분명 전생의 잘못을 바로잡을 기회다. \"이번에야말로 누군가를 해치고 빼앗는 삶이 아니라 지키고 가꾸는 삶을 살리라.\" 그렇게 이번 생을 바꿀 열쇠로 전생에 제 손으로 폐위시켰던 정적(政敵) 황태자를 선택하고 시녀로서 보좌하며 모든 게 잘 풀려가는 것 같았는데... \"레오나, 같이 여길 떠나자.\" 무언가 잘못된 것 같다. 냉정하고 무심한 줄만 알았던 황태자의 비밀과 세상에 감춰진 진실이 드러나고, 멸망의 그림자가 제국을 덮쳐온다.",
