        "synopsis":  "유일한 혈육이었던 언니를 잃고, 언니가 낳은 아들인 루시안을 홀로 키우고 있는 루첼라. 어느 날 그녀는 이 세계가 책 속이며, 루시안이 먼 훗날 악당으로 성장한다는 사실을 깨닫고 만다. 그것도 주인공을 괴롭히다 끔살당하는 엄청난 악역으로! \u0027사랑스러운 내 조카를 죽게 만들 수는 없어!\u0027 언니와의 약속을 지키기 위해. 또 사랑하는 조카를 살리기 위해. 그녀는 루시안을 악당이 아닌 바른 아이로 키우겠다 다짐한다. 그런데. \"이모, 나는 있지 이모가 후작 아저씨랑 결혼했으면 좋겠어.\" 얘는 잘 크기만 해도 모자랄 판에 이상한 소리를 하지 않나. \"우리 삼촌은 언니 신랑감으로 모자라긴 하지만...... 얼굴은 봐줄 만하니까요.\" 원작 여주라는 애는 진지하게 맞선을 주도하고. \"저도 그 의견에 동의합니다.\" 여주 삼촌은 말도 안되는 소리에 고개를 끄덕이느라 바쁘다. \"미안하지만 전 우리 루시안을 바르게 키우기 전까지는 결혼할 생각이 없어요.\" \"그 말은, 루시안을 바르게 키우기만 하면 된다는 소리입니까?\" \"그, 그건…….\" \"알겠습니다.\" 그것도 모자라 왜 다들 눈을 빛내는 건데!",
