        "synopsis":  "언제 어디서 읽은 소설 안에 빙의될지 모르는 대 빙의 시대에 병렬독서는 위험하다. “장문인, 사문 앞에 웬 갓난아기가!” 뽀짝 육아물 로판과 피가 튀기고 의와 협을 부르짖는 무협 소설을 같이 읽은 대가로 무협 육아물이라는 별 혼종에 빙의할 수 있으니 말이다. 심지어 클리셰인 명문 오대세가 막내딸도 아니고 부모도 없이 험난한 산꼭대기 화산파 앞에 버려진 아기라니! “그래, 막내야! 걸음마보다 검을 먼저 휘둘렀다는 전설을 남기는 거다!” “매화! 화산파의 일원이라면 응당 매화를 피워내야지!” 걷지도 못하는 아기한테 검 쥐여 주면서 양산형 전설 만들지 마. “무당파 놈들은 이겨야지, 무당파 놈들은! 우리가 대체 언제까지 천하제일검문은 무당이라는 소리를 듣고 살아야 하냐!” 어른들이 애들 어깨에 과도한 부담을 얹어주면 쓰냐? 심지어 어릴 때 자기 집으로 오라며 나를 살살 꼬시던 남궁세가 도련놈은 다시 만난 나를 알아보지 못하는 건 둘째 치고... “화산의 검은 겨우 이 정도냐? 그 화산파라 기대 좀 했더니, 화산도 별거 아니네.” 너어는 그냥 입을 열지 마라, 하. 앞으로는 한 번에 한 권씩만 읽을 테니까 저 좀 정통 육아물 로판으로 보내주시면 안 될까요? *** 남궁세헌이 덥석 내 양어깨를 붙잡았다. “야, 너...다른 사람이랑 대련하지 마.” “패배의 충격으로 머리가 회까닥 돌았니. 그게 가능하겠냐?” “아, 그런가...” 멍하니 동조하며 고개를 끄덕이던 남궁세헌이 말을 바꿨다. “그러면 다른 사람이랑 대련 끝나고 그렇게 웃지 마.” 느릿하게 눈을 깜빡인 그가 새까만 눈동자로 빤히 나를 내려다보았다. “나 이겼을 때만 그렇게 웃어줘.”",
